Ok, My first pass at implementing this didn't work. The fog became visible from only certain angles when the camera was outside the Fog, though it seemed to behave correctly from inside. I've looked at the code some more, but I still don't really understand how this code is culling froxels so I'm a bit stymied. Is there a cull check methodology used for the AABB of normal objects? Since we know the position of each corner of each froxel could we use that same methodology on the froxels?

This is the code I tried, in case it's relevant.
```
// Tracking just the corners of the fog volume can result in missing some fog:
// when the camera's near plane is inside the fog, we must always consider the entire screen
Vector3 near_plane_corner(frustum_near_size.x, frustum_near_size.y, z_near);
float expand = near_plane_corner.length();
bool x_is_inside = (cam_position.x > (corner_min.x - expand) && cam_position.x < (corner_max.x + expand));
bool y_is_inside = (cam_position.y > (corner_min.y - expand) && cam_position.y < (corner_max.y + expand));
bool z_is_inside = (cam_position.z > (corner_min.z - expand) && cam_position.z < (corner_max.z + expand));
if ( x_is_inside || y_is_inside || z_is_inside) {
	if (x_is_inside) {
		froxel_min.x = 0;
		froxel_max.x = int32_t(fog->width);
	}
	if (y_is_inside) {
		froxel_min.y = 0;
		froxel_max.y = int32_t(fog->height);
	}
	if (z_is_inside) {
		froxel_min.z = 0;
		for (int j = 0; j < 8; j++) {
			froxel_max.z = MAX(froxel_max.z, froxels[j].z);
		}
	}
} else {
	// Camera is guaranteed to be outside the fog volume
	for (int j = 0; j < 8; j++) {
		froxel_min = froxel_min.min(froxels[j]);
		froxel_max = froxel_max.max(froxels[j]);
	}
}
